import {initialState} from './core.mjs';
let connection;
export function openDB(){if(connection)return Promise.resolve(connection);return new Promise((resolve,reject)=>{const request=indexedDB.open('citywalk-for-two',1);request.onupgradeneeded=()=>request.result.createObjectStore('state');request.onerror=()=>reject(Error('浏览器暂时无法打开本机存储。请退出无痕模式后重试。'));request.onblocked=()=>reject(Error('请关闭其他一起走走页面，再重试。'));request.onsuccess=()=>{connection=request.result;connection.onversionchange=()=>{connection.close();connection=null;};resolve(connection);};});}
export async function readState(){const db=await openDB();return new Promise((resolve,reject)=>{const tx=db.transaction('state','readonly');const req=tx.objectStore('state').get('current');req.onsuccess=()=>resolve(req.result||initialState());req.onerror=()=>reject(Error('读取本机记录失败，请稍后重试。'));});}
export async function updateState(mutator){const db=await openDB();return new Promise((resolve,reject)=>{const tx=db.transaction('state','readwrite');const store=tx.objectStore('state');let next,result,reason;const req=store.get('current');req.onsuccess=()=>{try{next=req.result||initialState();result=mutator(next);if(result instanceof Promise)throw Error('存储操作不能包含异步步骤。');next.revision=(next.revision||0)+1;store.put(next,'current');}catch(e){reason=e;tx.abort();}};tx.oncomplete=()=>resolve({state:next,result});tx.onerror=()=>reject(reason||Error('保存失败，可能是设备空间不足。此操作未保存，请重试或导出备份。'));tx.onabort=()=>reject(reason||Error('保存中断，此操作未提交，请重试。'));});}
